(() => {
const clubLogo='data:image/png;base64,';
const palette=['#ffffff','#fbd0b2','#eee0bd','#b9e6f5'];
const names=['Mercearia','Carnes e congelados','Bebidas','Limpeza e cuidados'];
function design(){
 if(!state.design)state.design={headerColor:'#ec2926',priceColor:'#900d0b',bannerMode:'compose',repeatText:'ECONOMIA TODO DIA É AQUI!',sections:[0,1].map(()=>names.map((name,i)=>({name,color:palette[i],rows:[2,2,1,1][i],texture:i===2?'wood':'plain',image:''})))};
 if(!Array.isArray(state.design.pageLayout))state.design.pageLayout=[{header:true,footer:false},{header:false,footer:true}];
 if(!state.design.weekly)state.design.weekly={title:'OFERTAS VÁLIDAS DE',days:'',note:'OU ENQUANTO DURAREM NOSSOS ESTOQUES',x:98,y:98,width:28,background:'#f1272d',border:'#00a651',text:'#fff12b',visible:true};
 return state.design;
}
const safeColor=(v,f)=>/^#[0-9a-f]{6}$/i.test(v)?v:f;
const safeImage=v=>/^data:image\/(png|jpeg|webp);base64,[a-z0-9+/=]+$/i.test(v||'')?v:'';
const limit=(v,min,max,f)=>Number.isFinite(Number(v))?Math.max(min,Math.min(max,Number(v))):f;
function weekDays(){const days=['DOM','SEG','TER','QUA','QUI','SEX','SÁB'];const a=new Date(state.start+'T12:00:00'),b=new Date(state.end+'T12:00:00');return Number.isNaN(+a)||Number.isNaN(+b)?'CONFIRA AS DATAS':days[a.getDay()]+' A '+days[b.getDay()]}
function weekDates(){const a=(state.start||'').split('-'),b=(state.end||'').split('-');return a.length===3&&b.length===3&&a[0]===b[0]&&a[1]===b[1]?a[2]+' a '+date(state.end):date(state.start)+' a '+date(state.end)}
function weeklyMarkup(interactive){const w=design().weekly,x=limit(w.x,0,100,98),y=limit(w.y,0,100,98),width=limit(w.width,20,60,28);return `<div class="weekly-badge" ${interactive?'data-design="settings" tabindex="0" role="button" aria-label="Editar dados da semana e posição"':''} style="left:${x}%;top:${y}%;width:${width}%;transform:translate(-${x}%,-${y}%);--week-bg:${safeColor(w.background,'#f1272d')};--week-border:${safeColor(w.border,'#00a651')};--week-text:${safeColor(w.text,'#fff12b')}"><div class="weekly-inner"><svg class="weekly-calendar" viewBox="0 0 80 80" aria-hidden="true"><rect x="5" y="12" width="70" height="63" rx="4" fill="none" stroke="currentColor" stroke-width="4"/><path d="M5 30H75M22 4V20M58 4V20" fill="none" stroke="currentColor" stroke-width="5"/>${[0,1,2].flatMap(r=>[0,1,2,3].map(c=>`<rect x="${13+c*15}" y="${38+r*11}" width="10" height="8" fill="currentColor"/>`)).join('')}</svg><div class="weekly-copy"><div class="weekly-title">${esc(w.title)}</div><div class="weekly-days">${esc(w.days||weekDays())}</div><div class="weekly-dates">${esc(weekDates())}</div><div class="weekly-note">${esc(w.note)}</div></div></div></div>`}
function weeklyFields(){const w=design().weekly;$('#settingsFields').insertAdjacentHTML('beforeend',`<fieldset class="design-controls"><legend>Quadro de validade do cabeçalho</legend><label>Exibir quadro<select data-weekly="visible"><option value="true" ${w.visible?'selected':''}>Sim</option><option value="false" ${!w.visible?'selected':''}>Não — o banner já contém as datas</option></select></label><label>Texto superior<input data-weekly="title" maxlength="50" value="${esc(w.title)}"></label><label>Dias da semana<input data-weekly="days" maxlength="30" placeholder="Automático conforme as datas" value="${esc(w.days)}"></label><label>Texto inferior<input data-weekly="note" maxlength="100" value="${esc(w.note)}"></label><p class="help">As datas vêm dos campos Início e Fim acima. Deixe os dias em branco para atualizar automaticamente.</p>${[['x','Posição horizontal',0,100],['y','Posição vertical',0,100],['width','Largura do quadro',20,60]].map(([k,label,min,max])=>`<label>${label} (%)<input type="number" min="${min}" max="${max}" step="1" data-weekly="${k}" value="${limit(w[k],min,max,k==='width'?28:98)}"></label>`).join('')}<p class="help">Posição 0 = esquerda/topo; 100 = direita/base. As posições se adaptam ao computador e ao celular. O quadro aparece apenas nas páginas com cabeçalho.</p>${[['background','Fundo'],['border','Borda'],['text','Calendário e textos']].map(([k,label])=>`<label>${label}<input type="color" data-weekly="${k}" value="${safeColor(w[k],'#fff12b')}"></label>`).join('')}</fieldset>`)}
const originalFlyer=flyerHTML;
flyerHTML=function(pg,interactive=true){
 const d=design(),template=document.createElement('template');template.innerHTML=originalFlyer(pg,interactive);
 const root=template.content,header=root.querySelector('.flyer-header');
 header.classList.add('reference-header');header.style.setProperty('--banner-red',safeColor(d.headerColor,'#ec2926'));
 if(state.headerImage&&d.bannerMode==='image'){header.classList.add('full-banner');header.style.backgroundImage=`url('${safeImage(state.headerImage)}')`;header.innerHTML='<span class="sr-only">'+esc(state.brand)+' — '+esc(state.headline)+'</span>'}
 else {header.style.backgroundImage=state.headerImage?`url('${safeImage(state.headerImage)}')`:'';header.insertAdjacentHTML('beforeend',`<div class="banner-pattern" aria-hidden="true">${Array(9).fill(`<span>${esc(d.repeatText)}</span>`).join('')}</div>`)}
 const grid=root.querySelector('.products-grid'),offers=[...grid.children];grid.classList.add('reference-sections');grid.style.setProperty('--offer-red',safeColor(d.priceColor,'#900d0b'));grid.replaceChildren();
 offers.forEach((offer,offerIndex)=>{
 const product=state.products[pg*30+offerIndex];
 const title=offer.querySelector('.offer-name');if(title&&title.textContent.length>65)title.classList.add('long-copy');
 if(offer.classList.contains('empty-offer'))return;
 const image=offer.querySelector('.offer-image,.offer-placeholder'),desc=offer.querySelector('.offer-desc'),price=offer.querySelector('.offer-price'),old=offer.querySelector('.old-price'),badge=offer.querySelector('.offer-badge');
 if(price){const integer=[...price.childNodes].filter(n=>n.nodeType===3).map(n=>n.textContent).join('').replace(/\D/g,'');price.classList.add(integer.length>=4?'price-extra-long':integer.length>=3?'price-long':'price-short')}
 const copy=document.createElement('div');copy.className='offer-copy';if(title)copy.append(title);if(desc)copy.append(desc);offer.append(copy);
 const tag=document.createElement('div');tag.className='offer-price-tag';
 if(offer.classList.contains('is-club')){
   badge?.remove();tag.classList.add('club-price-tag');
   tag.innerHTML=`<div class="club-tag-heading club-logo-heading"><img src="${clubLogo}" alt="Clube Redeconomia"></div>`;
   if(old&&old.textContent.trim()){old.textContent=old.textContent.replace(/^De R\$/,'de');tag.append(old)}
   if(price){
 const reais=[...price.childNodes].filter(n=>n.nodeType===3).map(n=>n.textContent).join('').trim();
 const cents=(price.querySelector('sup')?.textContent||'00').replace(/^,/, '');
 if(/4$/.test(reais))price.classList.add('reais-ends-four');
 price.innerHTML=`<span class="club-por">POR</span><span class="club-reais">${esc(reais)}</span><sup class="club-cents">,${esc(cents)}</sup>`;
 tag.append(price)
 }
 }else{if(old&&old.textContent.trim())tag.append(old);if(price){const cents=price.querySelector('sup');if(cents)cents.textContent=','+cents.textContent.replace(/^,/, '');tag.append(price)}}
 if(product.priceLayout==='equivalent'){
 offer.classList.remove('is-club');offer.classList.add('is-equivalent');badge?.remove();
 const top=money(product.price).split(','),value=String(product.promoPrice||'').replace(',','.');
 const bottom=value!==''&&Number.isFinite(Number(value))?money(Number(value)).split(','):['—',''];
 tag.className='offer-price-tag equivalent-tag';
 tag.innerHTML=`<div class="equivalent-top"><div class="equivalent-number">${esc(top[0])}<sup>,${esc(top[1])}</sup><small>${esc(product.unit||'cada')}</small></div><div class="equivalent-copy">${esc(product.promoText||'NESTA EMBALAGEM SAI POR')}</div></div><div class="equivalent-bottom"><div class="equivalent-number">${esc(bottom[0])}<sup>${bottom[1]?','+esc(bottom[1]):''}</sup><small>Cada</small></div></div>`;
 }
 offer.append(tag);
 });
 let offset=0;
 (d.sections?.[pg]||[]).forEach((s,i)=>{const count=Math.min(30-offset,Math.max(0,Number(s.rows)||0)*5);if(!count)return;const section=document.createElement('section');section.className='offer-section '+(s.texture==='wood'?'wood-texture':'');section.style.setProperty('--section-color',safeColor(s.color,palette[i]));section.style.setProperty('--section-rows',count/5);section.style.flex=String(count/5);if(safeImage(s.image))section.style.backgroundImage=`url('${s.image}')`;section.innerHTML=`<div class="section-caption" ${interactive?'data-design="brand"':''}>${esc(s.name)}</div><div class="section-offers"></div>`;offers.slice(offset,offset+count).forEach(o=>section.lastElementChild.append(o));grid.append(section);offset+=count});
 if(offset<30){const section=document.createElement('section');section.className='offer-section';section.style.flex=String((30-offset)/5);section.innerHTML='<div class="section-offers"></div>';offers.slice(offset).forEach(o=>section.lastElementChild.append(o));grid.append(section)}
 root.querySelector('.validity-bar')?.remove();
 if(d.weekly.visible)header.insertAdjacentHTML('beforeend',weeklyMarkup(interactive));
 const layout=d.pageLayout[pg]||{header:pg===0,footer:pg===1};
 if(!layout.header){header.remove();root.querySelector('.validity-bar')?.remove();root.querySelector('.flyer-section')?.remove();grid.classList.add('without-header')}
 const footer=root.querySelector('.flyer-footer');
 if(!layout.footer){
   const credit=footer.querySelector('.footer-note');
   if(credit&&state.products.slice(pg*30,pg*30+30).some(p=>p.imageSource)){
     const note=document.createElement('div');note.className='standalone-photo-credit';note.innerHTML='Fotos: colaboradores do Open Food Facts · <a href="https://creativecommons.org/licenses/by-sa/3.0/" target="_blank" rel="noopener">CC BY-SA 3.0</a> · imagens recortadas. Fontes nos produtos.';footer.replaceWith(note);
   }else footer.remove();
 }else if(!layout.header){footer.insertAdjacentHTML('afterbegin',`<div class="footer-validity">OFERTAS VÁLIDAS DE ${date(state.start)} A ${date(state.end)}</div>`)}
 return template.innerHTML;
};
const originalFields=renderFields;
renderFields=function(){originalFields();if(tab==='settings'){weeklyFields();return}if(tab!=='brand')return;const d=design();$('#brandFields').insertAdjacentHTML('afterbegin',`<fieldset class="design-controls"><legend>Estilo da referência</legend><p class="help">Fundos contínuos, sem caixas individuais. Cada linha tem 5 produtos na impressão. Edite as divisões de cada página abaixo.</p><label>Vermelho do cabeçalho<input type="color" data-design-field="headerColor" value="${safeColor(d.headerColor,'#ec2926')}"></label><label>Cor dos preços tradicionais<input type="color" data-design-field="priceColor" value="${safeColor(d.priceColor,'#900d0b')}"></label><label>Texto repetido no cabeçalho<input data-design-field="repeatText" maxlength="100" value="${esc(d.repeatText)}"></label><label>Imagem do cabeçalho<select data-design-field="bannerMode"><option value="compose" ${d.bannerMode==='compose'?'selected':''}>Fundo com textos editáveis por cima</option><option value="image" ${d.bannerMode==='image'?'selected':''}>Banner pronto, sem textos por cima</option></select></label><p class="help">Envie seu banner em “Imagem do cabeçalho” abaixo. Tamanho recomendado: 1366 × 493 px (proporção 2,77:1).</p>${[0,1].map(pg=>`<details ${pg===page?'open':''}><summary>Divisões da página ${pg+1}</summary><div class="page-layout-controls"><label>Cabeçalho da página ${pg+1}<select data-page-layout="${pg}:header"><option value="true" ${d.pageLayout[pg].header?'selected':''}>Mostrar cabeçalho</option><option value="false" ${!d.pageLayout[pg].header?'selected':''}>Sem cabeçalho</option></select></label><label>Rodapé da página ${pg+1}<select data-page-layout="${pg}:footer"><option value="true" ${d.pageLayout[pg].footer?'selected':''}>Mostrar rodapé</option><option value="false" ${!d.pageLayout[pg].footer?'selected':''}>Sem rodapé</option></select></label></div>${d.sections[pg].map((s,i)=>`<div class="section-editor"><strong>Bloco ${i+1}</strong><label>Nome da divisão<input data-section="${pg}:${i}:name" maxlength="60" value="${esc(s.name)}"></label><div class="two-cols"><label>Cor de fundo<input type="color" data-section="${pg}:${i}:color" value="${safeColor(s.color,palette[i])}"></label><label>Textura<select data-section="${pg}:${i}:texture"><option value="plain" ${s.texture==='plain'?'selected':''}>Lisa</option><option value="wood" ${s.texture==='wood'?'selected':''}>Amadeirada</option></select></label></div><label>Linhas (5 itens por linha)<input type="number" min="0" max="6" data-rows="${pg}:${i}" value="${s.rows}"></label><label class="button">Enviar fundo<input type="file" accept="image/*" data-section-image="${pg}:${i}" hidden></label>${s.image?`<button class="text-button" data-section-clear="${pg}:${i}">Remover fundo enviado</button>`:''}</div>`).join('')}<button class="button dark full" data-apply-rows="${pg}">Aplicar distribuição da página ${pg+1}</button><p class="help">A soma deve ser 6 linhas (30 produtos). Use 0 para ocultar um bloco. Reordene os produtos no campo “Posição” de cada oferta.</p></details>`).join('')}</fieldset>`)};
 document.addEventListener('input',e=>{const wk=e.target.dataset.weekly;if(wk){const w=design().weekly;w[wk]=wk==='visible'?e.target.value==='true':['x','y','width'].includes(wk)?limit(e.target.value,wk==='width'?20:0,wk==='width'?60:100,wk==='width'?28:98):e.target.value;persist();render();return;}const k=e.target.dataset.designField,s=e.target.dataset.section;if(k){design()[k]=e.target.value;persist();render()}if(s){const [pg,i,key]=s.split(':');design().sections[pg][i][key]=e.target.value;persist();render()}});
 document.addEventListener('change',async e=>{if(e.target.dataset.pageLayout){const [pg,key]=e.target.dataset.pageLayout.split(':');design().pageLayout[pg][key]=e.target.value==='true';persist();render();return;}const key=e.target.dataset.sectionImage;if(!key)return;try{const [pg,i]=key.split(':');design().sections[pg][i].image=await readImage(e.target.files[0],1200);persist();render();renderFields()}catch(err){toast(err.message)}});
 document.addEventListener('click',e=>{const apply=e.target.closest('[data-apply-rows]'),clear=e.target.closest('[data-section-clear]');if(apply){const pg=+apply.dataset.applyRows,values=$$(`[data-rows^="${pg}:"]`).map(x=>Number(x.value));if(values.some(n=>!Number.isInteger(n)||n<0||n>6)||values.reduce((a,b)=>a+b,0)!==6)return toast('A distribuição precisa somar 6 linhas, ou 30 produtos.');values.forEach((n,i)=>design().sections[pg][i].rows=n);persist();render();toast('Divisões atualizadas.')}if(clear){const [pg,i]=clear.dataset.sectionClear.split(':');design().sections[pg][i].image='';persist();render();renderFields()}});
 const beforeAdjustFields=renderFields;
 const clubAdjust=()=>{const d=design();return d.clubAdjust||(d.clubAdjust={art:80,font:100,x:50,y:59})};
 renderFields=function(){beforeAdjustFields();if(tab!=='brand')return;const a=clubAdjust();$('#brandFields').insertAdjacentHTML('afterbegin',`<fieldset class="design-controls"><legend>Ajustar selo do clube</legend><p class="help">As mudanças aparecem em todas as ofertas de clube, inclusive na impressão.</p>${[['art','Tamanho da arte',50,120],['font','Tamanho do preço',70,120],['x','Posição horizontal do preço',40,60],['y','Posição vertical do preço',56,68]].map(([key,label,min,max])=>`<label>${label}: <output id="clubValue-${key}">${a[key]}%</output><input type="range" min="${min}" max="${max}" step="1" data-club-adjust="${key}" value="${a[key]}"></label>`).join('')}<button class="button" id="resetClubAdjust">Restaurar ajuste padrão</button></fieldset>`);$('#resetClubAdjust').onclick=()=>{design().clubAdjust={art:80,font:100,x:50,y:59};persist();render();renderFields()}};
 const beforeAdjustFlyer=flyerHTML;
 flyerHTML=function(pg,interactive=true){const html=beforeAdjustFlyer(pg,interactive),a=clubAdjust(),t=document.createElement('template');t.innerHTML=html;t.content.querySelectorAll('.club-price-tag').forEach(el=>{el.style.setProperty('--club-art-scale',limit(a.art,50,120,80)/100);el.style.setProperty('--club-font-scale',limit(a.font,70,120,100)/100);el.style.setProperty('--club-price-left',(limit(a.x,40,60,50)-37)+'%');el.style.setProperty('--club-price-top',limit(a.y,56,68,59)+'%')});return t.innerHTML};
 document.addEventListener('input',e=>{const k=e.target.dataset.clubAdjust;if(!k)return;clubAdjust()[k]=Number(e.target.value);$('#clubValue-'+k).textContent=e.target.value+'%';persist();render()});
 render();
})();
